window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d0b41532b5bea2d7"]={"versions": [{"id": "FIG-d0b41532b5bea2d7", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (BSW-Modul Ethernet Switch Driver, EthSwt). Das Diagramm spezifiziert die Konfigurationsstruktur und Modellbeziehungen für den SPI-basierten Zugriff des Ethernet-Switch-Treibers auf den externen SPI-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Konfigurationselemente und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>EthSwtConfig</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Wurzel-/Hauptkonfigurationscontainer für den Switch-Treiber. Enthält über die Kompositionsrolle <code>+subContainer</code> den Container <code>EthSwtSpi</code>.</li>\n<li><code>EthSwtSpi</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1): Optionaler Konfigurationscontainer für SPI-spezifische Einstellungen. Beinhaltet über <code>+subContainer</code> den Subcontainer <code>EthSwtSpiSequence</code>.</li>\n<li><code>EthSwtSpiSequence</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Definiert eine SPI-Sequenz für den Switch-Treiber. Beinhaltet:</li>\n<li><code>EthSwtSpiAccessSynchronous</code> (<code>EcucBooleanParamDef</code>, Multiplizität 0..1) über die Kompositionsrolle <code>+parameter</code>.</li>\n<li><code>EthSwtSpiSequenceName</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität 0..*) über die Kompositionsrolle <code>+reference</code>.</li>\n<li><code>EthSwtSpiSequenceName</code> verweist über die gerichtete Referenzassoziation <code>+destination</code> auf den externen Container <code>SpiSequence</code>.</li>\n<li><code>SpiSequence</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*, Herkunft <code>(from SPI)</code>): Externer Konfigurationscontainer des SPI-Treibers. Enthält über <code>+parameter</code>:</li>\n<li><code>SpiSequenceId</code> (<code>EcucIntegerParamDef</code>, Attribute: <code>symbolicNameValue = true</code>, <code>max = 255</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm ist ein statisches Konfigurationsmetamodell und stellt keine dynamischen Laufzeitsequenzen oder Zustandsübergänge dar. Die modellierte Referenzbeziehung legt fest, wie zur Konfigurations- oder Generierungszeit die Zuordnung von Switch-SPI-Sequenzen zu Sequenzen des SPI-Handlers/Treibers aufgelöst wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurationsparameter sind normativ verbindlich für die Generierung und Konfiguration des EthSwt-Treibers:</p>\n<ul class=\"fig-list\">\n<li>Die Aktivierung der SPI-Kopplung erfolgt bedingt über die Multiplizität von <code>EthSwtSpi</code> (0..1).</li>\n<li><code>EthSwtSpiSequenceName</code> ist als <code>EcucSymbolicNameReferenceDef</code> modelliert und erfordert die Referenzierung einer gültigen <code>SpiSequence</code>.</li>\n<li><code>SpiSequenceId</code> definiert einen symbolischen Namen (<code>symbolicNameValue = true</code>) mit Wertebereich bis maximal 255.</li>\n<li>Synchroner vs. asynchroner SPI-Zugriff wird über den booleschen Parameter <code>EthSwtSpiAccessSynchronous</code> gesteuert.</li>\n</ul>"}, {"id": "FIG-94b544fb7d42fd59", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (BSW-Modul Ethernet Switch Driver, EthSwt). Das Diagramm spezifiziert die Konfigurationsstruktur und Modellbeziehungen für den SPI-basierten Zugriff des Ethernet-Switch-Treibers auf den externen SPI-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Konfigurationselemente und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>EthSwtConfig</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Hauptkonfigurationscontainer für den Switch-Treiber. Enthält über die Kompositionsrolle <code>+subContainer</code> den Container <code>EthSwtSpi</code>.</li>\n<li><code>EthSwtSpi</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1): Konfigurationscontainer für SPI-spezifische Einstellungen. Beinhaltet über <code>+subContainer</code> den Subcontainer <code>EthSwtSpiSequence</code>.</li>\n<li><code>EthSwtSpiSequence</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Definiert eine SPI-Sequenz für den Switch-Treiber. Beinhaltet:</li>\n<li><code>EthSwtSpiAccessSynchronous</code> (<code>EcucBooleanParamDef</code>, Multiplizität 0..1) über die Kompositionsrolle <code>+parameter</code>.</li>\n<li><code>EthSwtSpiSequenceName</code> (<code>EcucReferenceDef</code>, Multiplizität 0..*, Attribut: <code>requiresSymbolicNameValue = true</code>) über die Kompositionsrolle <code>+reference</code>.</li>\n<li><code>EthSwtSpiSequenceName</code> verweist über die gerichtete Referenzassoziation <code>+destination</code> auf den externen Container <code>SpiSequence</code>.</li>\n<li><code>SpiSequence</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Konfigurationscontainer des SPI-Treibers. Enthält über <code>+parameter</code>:</li>\n<li><code>SpiSequenceId</code> (<code>EcucIntegerParamDef</code>, Attribute: <code>symbolicNameValue = true</code>, <code>max = 255</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm ist ein statisches Konfigurationsmetamodell und stellt keine dynamischen Laufzeitsequenzen oder Zustandsübergänge dar. Die modellierte Referenzbeziehung legt fest, wie zur Konfigurations- oder Generierungszeit die Zuordnung von Switch-SPI-Sequenzen zu Sequenzen des SPI-Handlers/Treibers aufgelöst wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurationsparameter sind normativ verbindlich für die Generierung und Konfiguration des EthSwt-Treibers:</p>\n<ul class=\"fig-list\">\n<li>Die Aktivierung der SPI-Kopplung erfolgt bedingt über die Multiplizität von <code>EthSwtSpi</code> (0..1).</li>\n<li><code>EthSwtSpiSequenceName</code> ist als generische <code>EcucReferenceDef</code> mit der expliziten Bedingung <code>requiresSymbolicNameValue = true</code> typisiert und referenziert eine <code>SpiSequence</code>.</li>\n<li><code>SpiSequenceId</code> definiert einen symbolischen Namen (<code>symbolicNameValue = true</code>) mit Wertebereich bis maximal 255.</li>\n<li>Synchroner vs. asynchroner SPI-Zugriff wird über den optionalen booleschen Parameter <code>EthSwtSpiAccessSynchronous</code> gesteuert.</li>\n</ul>"}], "trans": [{"from": "FIG-d0b41532b5bea2d7", "to": "FIG-94b544fb7d42fd59", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>EthSwtSpiSequenceName</code>: Typ von <code>EcucSymbolicNameReferenceDef</code> zu <code>EcucReferenceDef</code> geändert.</li>\n<li><code>EthSwtSpiSequenceName</code>: Attribut <code>requiresSymbolicNameValue = true</code> hinzugefügt.</li>\n<li><code>SpiSequence</code>: Paketursprungshinweis <code>(from SPI)</code> entfernt.</li>\n<li>Sämtliche Klassenkopf- und Rollenbeschriftungen: Leerzeichen vor dem Doppelpunkt entfernt (z. B. <code>EthSwtConfig :</code> zu <code>EthSwtConfig:</code>, <code>+parameter</code>, <code>+subContainer</code>).</li>\n</ul>"}]};
